import{_ as a,o as s,c as o,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"An Anatomy of Vision-Language-Action Models: From Modules to Milestones and Challenges","description":"","frontmatter":{"title":"An Anatomy of Vision-Language-Action Models: From Modules to Milestones and Challenges","arxiv":"2512.11362","date":"2025-12-12","authors":"Chao Xu, Suyu Zhang, Yang Liu, Baigui Sun, Weihong Chen, Bo Xu, Qi Liu, Juncheng Wang, Shujun Wang, et al.","categories":"cs.RO","topics":"通用具身智能, VLA 综述, 研究挑战分类","outline":[2,2]},"headers":[],"relativePath":"papers/2512.11362.md","filePath":"papers/2512.11362.md","lastUpdated":null}'),e={name:"papers/2512.11362.md"};function r(i,t,l,p,u,h){return s(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="an-anatomy-of-vision-language-action-models-from-modules-to-milestones-and-challenges" tabindex="-1">An Anatomy of Vision-Language-Action Models: From Modules to Milestones and Challenges <a class="header-anchor" href="#an-anatomy-of-vision-language-action-models-from-modules-to-milestones-and-challenges" aria-label="Permalink to &quot;An Anatomy of Vision-Language-Action Models: From Modules to Milestones and Challenges&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2512.11362" target="_blank" rel="noreferrer">2512.11362</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-12-12</td></tr><tr><td><strong>作者</strong></td><td>Chao Xu, Suyu Zhang, Yang Liu, Baigui Sun, Weihong Chen, Bo Xu, Qi Liu, Juncheng Wang, Shujun Wang, et al.</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>用&quot;模块 → 里程碑 → 挑战&quot;的金字塔重排 VLA 综述结构，把 5 大挑战 15 个子挑战放到全文核心而非结尾，试图从&quot;方法目录&quot;变成&quot;问题空间地图&quot;。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>arXiv 的 HTML 版本是 <strong>v3</strong>（v1 提交于 2025-12-12，v2 于 12-18，v3 于 12-19），本文按 v3 撰写。作者共 14 位，frontmatter 取前 9 位 + et al.。这是一篇声明会持续更新的&quot;living survey&quot;，项目页 <code>suyuz1.github.io/VLA-Survey-Anatomy/</code>。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>这不是一篇提方法的论文，它要解决的是<strong>综述本身的组织方式问题</strong>。作者的诊断有两条。第一，现有 VLA 综述习惯把研究挑战放在结尾当一节高层展望，导致&quot;问题&quot;从未被系统拆解、比较、对照；对于想做出新贡献的研究者，一份问题清单是不够的，需要的是问题空间的结构化剖析。第二，多数综述按&quot;视觉方法一章、控制策略一章&quot;分类罗列，便于查阅但呈现的是碎片视图，无法说明这些碎片如何拼成一条演进中的研究路线，因而无法把新人从基础概念带到前沿。</p><p>这件事值不值得做，取决于你怎么看当前 VLA 领域的状态。2024 到 2025 两年里，方法数量爆炸而评测口径几乎没有统一，同一个 LIBERO 分数在不同论文里可以差好几个点（本任务此前多个批次反复遇到这一问题）。在这种情形下，一份把&quot;分歧点&quot;而不是&quot;方法名&quot;当作骨架的地图，确实有其价值——前提是这张地图的划分要有判别力。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>作者把已有综述分成两类。一类是聚焦子领域的深度综述：动作 tokenization、高效训练范式、后训练方法学等，颗粒度细但覆盖窄。另一类是系统性总览，按模型架构、输入模态或训练目标组织出分类学，给读者一份组件清单。</p><p>作者对第二类的批评是准确的：分类学告诉你&quot;有哪些做法&quot;，但不告诉你&quot;这些做法在争什么&quot;。举例来说，把&quot;离散动作空间&quot;和&quot;连续动作空间&quot;并列成两栏，读者看不到二者背后真正的分歧——是推理延迟、是多模态表达力、还是与预训练 LLM 词表的兼容性。</p><p>但这里也埋下了本文自身的隐患：<strong>用&quot;挑战&quot;当骨架并不天然比用&quot;方法&quot;当骨架更有判别力</strong>。挑战的边界通常比方法的边界更模糊，一篇论文可以同时属于三个挑战。这一点在 §9 会展开。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>把自己放回 2025 年底的位置。你要写一篇 VLA 综述，但已经有六七篇了，其中不乏覆盖面很全的。差异化只能来自结构。</p><p>第一个可用的观察是：<strong>读者不是按分类学学习的</strong>。一个新人进入 VLA，实际的路径是先搞清&quot;一个 VLA 由哪几块组成&quot;，再搞清&quot;这些块是怎么一步步演化到今天的&quot;，最后才关心&quot;现在卡在哪&quot;。这三段恰好构成一个金字塔：模块是底座，里程碑是中层，挑战是塔尖。</p><p>第二个观察是：如果挑战要当核心，就必须给出一个划分。什么样的划分是自然的？作者选择了一条&quot;通用智能体发育路线&quot;的隐喻——先建立最基础的感知-动作回路（表征），再让它能执行复杂指令并实时运行（执行），再让它跨本体跨环境扩展（泛化），再让它可信可部署（安全），而这一切都要有数据与评测基础设施托底。</p><p>第三步是承认篇幅约束并作取舍：既然要把深度留给挑战部分，模块部分就只做精简概览，并显式建议读者去看其他专门的架构分类学综述。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>一份综述的价值不在于列全了多少论文，而在于它给读者装上了什么样的&quot;提问框架&quot;。本文的赌注是：把 VLA 领域重排成&quot;五个发育阶段的挑战&quot;，读者在读到任何一篇新论文时都能立刻问出&quot;它在解决第几层的哪个子问题、代价是什么&quot;。金字塔结构服务的是学习路径，挑战分解服务的是研究选题。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>综述本身的&quot;pipeline&quot;就是它的三层结构。以一个具体读者的使用方式来讲：</p><p><strong>第一层（§2 基础模块）</strong>。把任意 VLA 拆成感知、大脑、动作三块，并指出各自的演化方向。感知侧：从普通视觉骨干 → 语言对齐的 ViT（CLIP/SigLIP）→ 再叠自监督几何表示（DINOv2）形成混合编码器（OpenVLA、GraspVLA、UniVLA 都是 SigLIP+DINOv2）；本体感受因维度低而普遍用 MLP 编码后拼接或 FiLM 融合。大脑侧：从纯 Transformer → DiT → 混合（VLM 主干 + flow matching 动作头，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是范例）→ 直接把完整 VLM 当大脑。动作侧：离散分箱 → 连续回归/生成 → 混合（<a href="/notes/papers/2506.07961">BridgeVLA</a> 连续平移 + 离散旋转；HiRT 末端位姿连续、夹爪离散）；解码方式对应自回归、非自回归、以及&quot;跨 chunk 自回归、chunk 内并行&quot;的混合。</p><p><strong>第二层（§3 里程碑）</strong>。按年份串成一条线：2017–2019 的 VLN 与 EmbodiedQA 立起闭环感知-动作的评测范式；2020–2021 的 ALFRED/BEHAVIOR 把长时程搬进来，CLIPort 首次证明互联网预训练表示能带来零样本泛化；2022 的 SayCan 引入分层、RT-1/RT-2 落成端到端；2023 的 PaLM-E 统一多模态输入空间、Diffusion Policy 引入生成式动作建模、Open X-Embodiment 提供跨本体数据；2024 的 Octo、OpenVLA、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、GR-2、3D-VLA；2025 走向多元化，涵盖人形全身控制、物理接地推理、显式视觉思维链、分层统一、以及规模律的早期证据。</p><p><strong>第三层（§4 挑战，全文核心）</strong>。5 个主挑战、15 个子挑战：</p><ul><li><strong>4.1 多模态对齐与物理世界建模</strong>：语义-感知-物理的鸿沟；从 2D 图像到时空表示；动态预测式世界模型（观测空间预测 vs 潜空间预测；用作策略增强 vs 用作显式规划器）。</li><li><strong>4.2 指令跟随、规划与实时执行</strong>：复杂/歧义指令解析；分层规划与任务分解（语言驱动 / 多模态中间量 / 技能库组合）；错误检测与自主恢复（人在回路 / 自纠错）；实时性与算力（静态架构优化如 <a href="/notes/papers/2506.07530">BitVLA</a>、动态解码优化如 <a href="/notes/papers/2503.20384">MoLe-VLA</a>/<a href="/notes/papers/2502.02175">VLA-Cache</a>/<a href="/notes/papers/2506.13725">CEED-VLA</a>/<a href="/notes/papers/2509.05614">SpecPrune-VLA</a>、动作表示优化如 <a href="/notes/papers/2507.01016">VQ-VLA</a>/<a href="/notes/papers/2508.20072">Discrete Diffusion VLA</a>、训练与系统层优化）。</li><li><strong>4.3 从泛化到持续适应</strong>：开放世界泛化；持续学习与增量技能；sim-to-real；在线交互与 RL。</li><li><strong>4.4 安全、可解释与可靠交互</strong>：约束式安全范式（<a href="/notes/papers/2503.03480">SafeVLA</a> 把危险行为建成 CMDP 里的 cost）vs 学习式对齐范式；过程可解释性与行为可预测性。</li><li><strong>4.5 数据构建与评测标准</strong>：多源异质数据的表征级统一、数据级增广、标准化与基准建设；评测基准的三条演进方向。</li></ul><p>每个主挑战末尾有一节&quot;Summary &amp; Trends + Directions&quot;，先概括当前主导做法的共性缺陷，再给出方向性主张（原生多模态架构、潜-物理-语义混合世界模型、自适应思考深度、形态无关表示、内生不确定性意识、仿真优先且以失败为中心的数据范式等）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>本文是综述，<strong>没有任何实验、消融或复现</strong>。它的&quot;证据&quot;完全是文献学的：把论文归入 15 个子挑战，并在附录用三张大表（代表性数据集 S1、代表性基准 S2、VLA 里程碑 S3）做清单化整理。这决定了本文的可证伪性主要落在两处。</p><p>第一处是<strong>分类的一致性</strong>：15 个子挑战是否互斥且穷尽。可以直接核对的是数量自洽性——3 + 4 + 4 + 2 + 2 = 15，与摘要一致。但互斥性并不成立，作者自己的行文就给出了反例：世界模型被放在 4.1.3（表征层），可它在 4.2.3 里又是错误恢复的主要手段；sim-to-real 被放在 4.3.3（泛化层），可 4.5.3 给出的解法是&quot;仿真优先&quot;的数据范式，属于数据层。同一篇论文（如 CoT-VLA）在 4.1.3、4.2.2、4.4.2 三处被反复引用，扮演三种不同角色。</p><p>第二处是<strong>方向性主张的可检验性</strong>。作者给出的方向大多是纲领式的（&quot;原生多模态架构&quot;&quot;内生不确定性意识&quot;&quot;把失败变成信号&quot;），措辞层面无法被数据反驳。其中最接近可检验的是 4.5.3 的判断：&quot;真实世界采集本质上不可扩展且嘈杂，二元成功率会掩盖关键失败模式&quot;——这一条与本任务此前多个批次的实测观察一致（大量论文的真机结果只有柱状图、每格 10–20 次试验、无置信区间）。</p><p>一个值得单独指出的内部张力：全文以&quot;表征 → 执行 → 泛化 → 安全 → 数据&quot;的发育顺序组织，把数据与评测放在最后当&quot;支撑性基础设施&quot;；但 4.5.2 本身论证的是评测标准跟不上模型进展、缺乏统一口径、任务过于短程、缺乏系统性探测前沿泛化的手段。如果评测确实是当前的约束性瓶颈，那么金字塔的层序就应当倒过来。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：(1) 本文的贡献是结构而非内容——把研究挑战从综述结尾提到全文核心，配以&quot;模块 → 里程碑 → 挑战&quot;的三层学习路径。(2) 五大挑战被组织成一条智能体发育路线：表征、执行、泛化、安全、数据与评测，共 15 个子挑战。(3) 模块部分刻意做薄，作者明确建议读者参阅其他架构分类学综述，说明本文不追求覆盖度而追求问题空间的可导航性。(4) 三条被反复点出的领域共性缺陷是：晚融合限制深层跨模态推理、动态预测在模仿物理而非理解因果、二元成功率掩盖失败模式。(5) 全文无实验、无形式化，可证伪性主要落在分类的互斥性与方向主张的可操作性上。</p><p><strong>3 句话版</strong>：一篇以问题而非方法为骨架的 VLA 综述，把 5 大挑战 15 个子挑战摆到全文中心，并按&quot;发育路线&quot;排序。它对领域现状的三条诊断（晚融合、伪物理、评测滞后）是准确的。但分类的互斥性不成立，且它把数据与评测排在发育路线末端，与它自己关于评测是瓶颈的论证相冲突。</p><p><strong>1 句话版</strong>：把 VLA 综述从方法目录改写成问题地图，代价是问题的边界比方法更模糊。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>五大挑战构成一条有先后的发育路线，且数据与评测是托底的&quot;支撑设施&quot;而非首要约束</strong>。</p><p>这条假设决定了全文的排版顺序、金字塔隐喻、以及每个挑战末尾&quot;Directions&quot;的写法。如果它不成立——即评测标准的缺失才是限制其他四项进展的因素——那么整张地图的层序需要重画。</p><p>论文自己提供了反证的材料。4.5.2 明确列出三条评测缺陷：口径不统一导致无法公平比较、任务过于短程无法测认知推理、缺乏系统性探测前沿泛化的手段。4.5.3 进一步说&quot;二元成功率会掩盖关键失败模式&quot;。把这两段与 4.3 的泛化挑战并读会得到一个尴尬的结论：<strong>在没有可信评测的前提下，&quot;泛化是否被解决&quot;这个问题根本无法被回答</strong>，于是 4.3 的所有进展叙事都建立在 4.5 承认不可靠的度量之上。这不是排版细节，而是逻辑上的循环依赖。</p><p>作者为发育路线提供的证据只有隐喻（&quot;建立感知-动作回路 → 跨本体扩展 → 可信部署&quot;）。全文没有任何跨挑战的定量依据（例如某类进展是否确实先于另一类发生），也没有讨论替代排序的可能。这使得该假设既是全文的组织原则，又是全文最未被检验的部分。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>综述的&quot;复现&quot;就是检验它的分类学是否可用。一周内可做：</p><ul><li><strong>材料</strong>：取 v1 提交日（2025-12-12）之后一个月内 arXiv cs.RO 上的 VLA 相关新论文，约 40–60 篇。这批论文对本文而言严格是&quot;未见样本&quot;。</li><li><strong>实现</strong>：请 3 位标注者独立把每篇论文归入 15 个子挑战之一（允许&quot;无法归入&quot;）。同时用同一批论文对另一篇结构不同的 VLA 综述（例如按架构分类的那类）做同样的归类。</li><li><strong>测量</strong>：三件事——(a) 标注者间一致性（Fleiss <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span>）；(b) 多标签率，即被至少两位标注者归到两个以上子挑战的论文比例；(c) 无法归入率。</li><li><strong>判据</strong>：若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> 低于 0.4，或多标签率超过 50%，说明 15 个子挑战不具备判别力，&quot;以挑战为骨架&quot;相对&quot;以方法为骨架&quot;没有带来更清晰的划分；若无法归入率显著高于对照综述，说明该分类学的覆盖有盲区。这组实验成本极低，却是任何分类学综述都应当自带而几乎没人做的自检。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是：<strong>&quot;挑战&quot;这一分类轴在 VLA 领域天然不可分割，因此以它为骨架必然产生高耦合、低判别力的划分，而作者用于弥补的手段（每个子挑战下再按解法分成 2–3 个 family）恰恰把结构悄悄退回成了方法分类学</strong>。</p><p>证据全在论文内部。4.1.3 把世界模型按&quot;表示空间&quot;（观测空间 vs 潜空间）与&quot;使用范式&quot;（策略增强 vs 显式规划）分成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>；4.2.2 把分层规划按&quot;中间表示类型&quot;分成语言 / 多模态中间量 / 技能库；4.2.4 把实时性按&quot;优化对象&quot;分成架构 / 解码 / 动作表示 / 训练与系统。这些二级划分全部是<strong>按方法</strong>做的。也就是说，真正承担信息组织功能的仍然是方法分类，&quot;挑战&quot;只是给它们套了一层标题。如果这一读法成立，本文相对已有综述的净增量就从&quot;新的组织范式&quot;降级为&quot;新的章节命名&quot;。</p><p>另一条独立攻击针对&quot;living survey&quot;的定位：一份声明会持续更新的综述，其分类学在任何时刻都可以被追加子类以吸收反例，因而不可证伪。要让它可评估，唯一的办法是给每个版本打上快照并冻结分类学，再用后续论文做前瞻性检验（即 §10 的实验）。作者提供了项目页与版本号，具备做这件事的条件，但没有做。</p><p>第三条是覆盖偏置：全文引用的方法绝大多数集中在 2024–2025，2022 年之前的工作只在里程碑一节以单句带过。对于一份自称&quot;新人的基础指南&quot;的综述，这意味着新人会习得一个&quot;VLA 起源于 RT-1&quot;的历史观，而模仿学习、语言条件策略、分层控制在此之前已有长期积累。一个廉价的检验：统计参考文献的年份分布，若 2024 年之后占比超过 70%，则&quot;基础指南&quot;这一定位与实际内容不符。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：本文（以及此前所有 VLA 综述）的输出形态是散文加大表。散文无法被查询、无法被验证、无法随领域更新自动重算。作者自己想做&quot;living survey&quot;，但载体仍是 PDF，更新只能靠人工重写。</p><p><strong>新的 framing</strong>：把综述从&quot;文本&quot;改成**&quot;带证据卡片的可查询图数据库&quot;<strong>。每篇被收录的论文对应一张结构化的 claim card，至少包含五个字段：它声称改善了什么量（指标名 + 基准 + 划分）、相对哪个基线、在什么骨干与算力下、做了哪些控制变量对照、以及</strong>哪些关键对照缺失**。挑战与子挑战不再是章节标题，而是图上的节点；论文-挑战边带权重（该论文对该挑战的证据强度）。</p><p>这样做的直接收益是三件综述现在做不到的事：(a) 自动检测跨论文数字不可比（同一基准同一模型在不同论文里给出不同值，本任务已多次遇到）；(b) 量化每个子挑战的&quot;证据密度&quot;与&quot;对照完备度&quot;，从而客观回答&quot;哪个方向被过度拥挤、哪个方向缺对照&quot;；(c) 计算挑战节点之间的耦合度，直接检验 §9 提出的&quot;发育路线是否成立&quot;。</p><p><strong>可借鉴的相邻工具</strong>：循证医学的系统综述已有成熟范式——PRISMA 流程规定检索式、纳入排除标准与偏倚评估；Cochrane 的 risk-of-bias 表就是本文所需 claim card 的现成模板；机器学习侧的 Papers-with-Code 式结构化榜单提供了指标-基准-数值的三元组 schema。把两者合并，就是一份&quot;具身智能版的系统综述&quot;。</p><p><strong>第一个实验</strong>：不必一开始就覆盖全领域。选一个边界清晰的子挑战——4.2.4&quot;实时执行与算力&quot;——它有明确的可比量（延迟、FLOPs、控制频率、成功率）。把该子挑战下已被本文引用的全部方法做成 claim card，重点填&quot;缺失对照&quot;字段。可以预期会立刻暴露一批系统性问题：加速比的分母是哪个基线、墙钟是否在同一张卡上测、质量下降是否用了与训练目标同源的指标。若这份卡片表能复现出本任务在多个加速批次中独立发现的那些矛盾（加速比口径不一、稀疏度与墙钟不成比例、质量指标与奖励同源），就证明结构化综述能自动做到散文综述做不到的事，这一形态才值得推广到其余 14 个子挑战。</p>',55)])])}const c=a(e,[["render",r]]);export{g as __pageData,c as default};
